function renderKeys(){if(current.type==='bass'){$('synth-controls').hidden=true;$('pent-label').style.display='none';$('family-label').textContent=current.family.toUpperCase();$('instrument-name').textContent=current.name;$('keys').replaceChildren();for(const [name,fn]of [['Open bass machine',openBass],['Bass on / off',toggleBass],['Next preset',nextBassPreset]]){const b=document.createElement('button');b.textContent=name;b.onclick=fn;$('keys').append(b);}$('play-hint').textContent='Build a bass line with 16 steps, accents and slides.';return;}if(current.type==='gallery'){$('family-label').textContent='CREATE & LISTEN';$('instrument-name').textContent='Listening Room';$('keys').replaceChildren();const b=document.createElement('button');b.textContent='Browse shared songs';b.onclick=openGallery;$('keys').append(b);$('play-hint').textContent='Listen to songs shared by other visitors.';return;}if(current.type==='notewall'){renderUtilityKeys();return;}$('synth-controls').hidden=current.type!=='synth';let pitched=current.midi!==undefined;$('family-label').textContent=current.family.toUpperCase();$('instrument-name').textContent=current.name;$('pent-label').style.display=pitched?'flex':'none';$('keys').replaceChildren();if(pitched){let notes=(current.notes||diatonic);notes.forEach((n,i)=>{let midi=current.midi+n,b=document.createElement('button');b.textContent=noteName(midi);b.dataset.midi=midi;b.className=[1,3,6,8,10].includes(midi%12)?'black':'';b.disabled=!isAllowed(midi);b.setAttribute('aria-label','Play '+noteName(midi));let sm=document.createElement('small');sm.textContent=instrumentKeys(current)[i]?.toUpperCase()||'';b.append(sm);let pointerHeld=false;b.onpointerdown=async e=>{e.preventDefault();pointerHeld=true;b.setPointerCapture(e.pointerId);const chosen=current;if(!await startSound()||!pointerHeld)return;if(chosen.type==='synth'){holdSynth('pointer:'+e.pointerId,midi,b);}else playNote(chosen,midi);};b.onpointerup=b.onpointercancel=e=>{pointerHeld=false;releaseSynth('pointer:'+e.pointerId);};b.onclick=e=>{if(e.detail===0)startSound().then(()=>playNote(current,midi));};$('keys').append(b);});$('synth-controls').hidden=current.type!=='synth';if(current.type==='steelpan'){const mode=document.createElement('button');mode.id='mobile-mode';mode.onclick=cycleMobileMode;$('keys').append(mode);refreshMobileMode();}$('play-hint').textContent=(current.type==='synth'?'Hold notes to sustain · ':'Click notes · ')+'Keyboard: '+instrumentKeys(current).slice(0,Math.min(notes.length,13)).toUpperCase().split('').join(' ');}else{let choices=current.type==='drums'?drums:['screen','listen'].includes(current.type)?['Choose '+(current.type==='screen'?'a movie':'a song')]:['Play '+current.name];choices.forEach((name,i)=>{let b=document.createElement('button');b.textContent=name;b.onclick=async()=>{await startSound();if(current.type==='drums')audio.play(drums[i]);else if(['screen','listen'].includes(current.type))openMedia(current.type);else playNote(current);};$('keys').append(b);});if(current.type==='drums'){let b=document.createElement('button');b.textContent='Open sequencer ↗';b.onclick=openDrums;$('keys').append(b);} $('play-hint').textContent=['screen','listen'].includes(current.type)?'Choose from media added in Teacher setup.':current.type==='drums'?'Play pads or open the 16-step sequencer.':'Click to play · Space to shake or strike';}}
