function selectStation(id,move=true){let s=specs.find(s=>s.id===id);if(!s)throw Error('Unknown station');releaseSynthHolds();current=s;if(!['notewall','gallery'].includes(s.type))experience.guide.select();refreshCreativeTools();renderNav();renderKeys();$('stations').classList.remove('mobile-open');document.body.classList.add('focused');if(move&&rig&&s.group){let offset=new THREE.Vector3(0,0,stationApproach(s,renderer.xr.isPresenting));offset.applyAxisAngle(new THREE.Vector3(0,1,0),s.rot||0);rig.position.set(s.x+offset.x,renderer?.xr.isPresenting?comfort.offset:0,s.z+offset.z);yaw=s.rot||0;pitch=s.type==='notewall'?.20:s.type==='synth'?-.20:['drums','bass','notewall','gallery','boomwhacker','gong','windchimes'].includes(s.type)?0:-.60;rig.rotation.y=yaw;if(!renderer.xr.isPresenting){desktop.zoom=1;fitDesktopStation();}if(renderer.xr.isPresenting){rig.updateMatrixWorld(true);renderer.xr.updateCamera(camera);const head=renderer.xr.getCamera(camera).getWorldPosition(new THREE.Vector3());rig.position.x+=s.x+offset.x-head.x;rig.position.z+=s.z+offset.z-head.z;resetControllerMotion();positionComfortMenu();positionRecorderMenu();}}playUI?.select();toast(s.type==='notewall'?'Song Station · record, save and open your songs':s.name+' · Tap to play'+(s.midi!==undefined?' · 5-note subset is optional':''));}
