$('overview').onclick=overview;$('collapse').onclick=()=>{$('stations').classList.toggle('collapsed');$('collapse').textContent=$('stations').classList.contains('collapsed')?'+':'−';};$('mobile-stations').onclick=()=>{$('stations').classList.toggle('mobile-open');$('stations').classList.remove('collapsed');};$('volume').oninput=e=>{audio.volume(muted?0:+e.target.value);$('video').volume=+$('volume').value;$('audio').volume=+$('volume').value;};$('pentatonic').onchange=e=>{releaseSynthHolds();pent=e.target.checked;renderKeys();barMeshes.forEach(m=>{if(m.userData.midi!==undefined)m.material.opacity=isAllowed(m.userData.midi)?1:.27;m.material.transparent=true;});};$('sound').onclick=async()=>{if(!soundOn){await startSound();return;}await startSound();muted=!muted;if(muted){audio.volume(0);$('video').muted=true;$('audio').muted=true;$('sound').textContent='Sound muted';}else{audio.volume(+$('volume').value);$('video').muted=false;$('audio').muted=false;$('sound').textContent='Sound on';}};
function panel(title){heldKeys.clear();releaseSynthHolds();for(const id of ['video','audio']){const el=$(id);if(el&&$('panel-content').contains(el)){el.hidden=true;document.body.append(el);}}$('panel').classList.remove('gallery-panel');$('panel-title').textContent=title;$('panel-content').replaceChildren();if(!$('panel').open)$('panel').showModal();return $('panel-content');}
$('close-panel').onclick=()=>$('panel').close();$('panel').addEventListener('click',e=>{if(e.target===$('panel')){let b=$('panel').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('panel').close();}});
$('help').onclick=()=>{let p=panel('Make yourself at home');p.innerHTML='<p><b>Desktop & touch</b><br>Choose an instrument at the top. Play shows one instrument; Explore room lets you walk around. Click or tap notes to play. Use the <kbd>arrow keys</kbd> to walk. Right-drag to look without playing notes (left-drag also works). Scroll over the room to move closer or farther from a selected instrument; <b>Fit instrument</b> restores its full view. <kbd>Shift</kbd> + <kbd>W A S D</kbd> also walks; use Q W E R T Y U I O P [ ] &#92; for the thirteen diatonic bars, including steelpan, and A S D F G H J K for boomwhackers. Notes go from low to high. The synthesizer keeps its piano-style key layout. Use <kbd>Space</kbd> for small percussion.</p><p><b>Have a MIDI keyboard?</b><br>Plug it into the device running this room, then choose Plug in a MIDI keyboard beside the playing controls (in VR: left thumbstick → More → MIDI Keyboard). Choose Connect keyboard and allow access if your browser supports MIDI. Only notes actually on the selected instrument will play; its range and F♯ / B♭ bars stay the same.</p><p><b>Outside the windows</b><br>A full day lasts six minutes (15 seconds per hour), with sunrise, sunset, a sun, moon and stars. Short rainstorms arrive about every four minutes, with occasional distant lightning and a rainbow afterward when there is daylight.</p><p><b>Seated play</b><br>Open Seated / height, switch on Seated mode, and enter VR while sitting comfortably. Your view and mallets move together to playing height. In VR, click the left thumbstick, then More → Reach / Height to adjust height, recalibrate, or move between instruments. Look forward and sit naturally when recalibrating.</p><p><b>In VR</b><br>Open this page in your headset browser and choose Enter VR. Point and pull a trigger to play. Tap instrument bars with the mallet tips for two-handed playing. Gentle taps sound softer; faster downward strikes sound stronger and brighter, with matching controller feedback. Light mallet sensitivity in Music settings makes gentle strokes easier. Rest a mallet on synth keys to sustain. Point at the floor and pull a trigger to teleport. Right thumbstick left/right turns 30°. Grip + shake plays the selected maracas or tambourine.</p><p><b>Gong & wind chimes</b><br>Find them in the back corner near the synthesizer. Strike the gong or tap and brush across the six chime tubes with your mallets. On desktop, click the instrument, use Space for the gong, or Q W E R T Y for the chimes. Both use acoustic recordings and work with Record, Overdub, My Songs and sharing. Chimes follow the room key. Let the tones ring and overlap.</p><p><b>Steelpan & musical mobile</b><br>Tap the thirteen labeled note areas with either mallet. The steelpan follows the room key and records like the other instruments. Above it, the mobile responds to live notes and recorded playback: low sounds move larger shapes, high sounds smaller ones, with colors for each instrument. The Mobile button cycles Calm, Lively and Off.</p><p><b>Drum & bass presets</b><br>Choose 20 drum rhythms or 40 bass lines from the machine’s preset buttons. Key / Mode changes the virtual Orff bars and bass together; stop playback first. Natural-note modes need no accidental bars. F major and D minor use B-flat; G major and D Mixolydian use F-sharp. Only natural bars, F-sharp and B-flat are available. Recorded notes retain their original pitches when you change the room key. Bass note edits stay within the selected scale.</p><p><b>Wall synthesizer</b><br>Hold its keys or controller trigger to sustain a note. Choose a waveform, then drag the envelope, filter and effect sliders. Delay and reverb combine with chorus, flanger or phaser. Choose from 24 presets. Try the four waveform pictures and Pluck, Hold or Swell envelopes above the keyboard. Brightness, Fade in, Fade out and Space are the main sliders; MORE opens the detailed sound and effect controls.</p><p><b>The note wall</b><br>The front screen shows every recorded instrument as colored notes on a piano roll, with percussion lanes below. Watch new notes appear while recording or overdubbing. Held synth notes grow until you lift the mallet or release the key. Choose My Songs at the front Song Station to play a saved song and see its notes here. The separate listening room is for publicly shared songs.</p><p><b>Loop recording</b><br>Click the left thumbstick to open the recorder: RECORD makes a new four-measure loop, OVERDUB adds a part, and STOP stops playback and keeps your work. Overdub stays on until you press it again, even when you change instruments. The stick-click metronome is on by default for both recording and overdubbing. Adjust its volume in Music settings, or use QUIETER / LOUDER under MORE in the VR recorder. The first beat is accented, and the click is not saved into your song. Drums and bass share one clock. Starting a second machine queues it for beat 1 of the next measure; the first keeps playing. Both show the same running step. A drum-machine measure repeats in time across the four measures. The Song Station always shows New Song, Record, Overdub, Play and Stop, with Save Song, My Songs and Undo Last Note just below. New Song offers to save before clearing notes, drums and bass. More holds settings and other undo options. Save opens a naming keyboard right in front of you and puts your song into My Songs on this device. Use Export / Import to move songs to another device. Click the left thumbstick to open or close the recorder directly in front of you. Record and Overdub close the panel so you can play. HEIGHT is inside the recorder. No menus are attached to your hands.</p><p class="panel-note">This is a solo music room. Steelpan, gong and wind chimes use acoustic recordings; other instruments are synthesized. Sound credits are in Settings. Each visitor plays independently. Teacher setup is saved on this device; use Export / Import to move the link list between devices. Setup is not password protected.</p>';};
function toggleStep(r,i){studio.drumPreset=null;refreshPresetLabels();pattern[r][i]=!pattern[r][i];if(recorder.drumPattern)recorder.drumPattern=pattern;updateSequence();}
function setBpm(n){configureLoop(Math.max(40,Math.min(200,Math.round(n))),recorder.bars);}
function clearPattern(){studio.drumPreset=null;refreshPresetLabels();pattern=Array.from({length:4},()=>Array(16).fill(false));if(recorder.drumPattern)recorder.drumPattern=pattern;updateSequence();}
function updateSequence(){studio.drumPreset=Object.keys(DRUM_PRESETS).find(name=>JSON.stringify(drumPreset(name))===JSON.stringify(pattern))||null;refreshPresetLabels();playing=recorder.state!=='stopped'&&!!recorder.drumPattern;worldCells.forEach(m=>{let r=m.userData.row,i=m.userData.step;m.material.color.setHex(pattern[r][i]?0xe2ae57:i%4===0?0x54736b:0x344f4a);});document.querySelectorAll('[data-seq]').forEach(b=>{let [r,i]=b.dataset.seq.split(',').map(Number);b.classList.toggle('on',pattern[r][i]);b.setAttribute('aria-pressed',String(pattern[r][i]));});if($('drum-play'))$('drum-play').textContent=playing?'Stop drums':'Start drums';}
async function toggleDrums(){if(!await startSound())return;stopPreview();recorder.toggleMachine('drums',pattern,studioNow());studio.drumStep=null;updateSequence();updateDrumPhase(studioNow());refreshRecorder();}
function updateDrumPhase(now){const source=songPreview.state==='playing'?songPreview:recorder;
 const drum=source.machinePhase('drums',now),bass=source.machinePhase('bass',now),next=drum.step;
 if(studio.drumStep!==next){studio.drumStep=next;worldCells.forEach(m=>{m.material.emissive.setHex(m.userData.step===next?0x8b7644:0);m.material.emissiveIntensity=.45;});}
 document.querySelectorAll('[data-seq]').forEach(b=>b.classList.toggle('current',+b.dataset.seq.split(',')[1]===next));
 document.querySelectorAll('[data-bass-step]').forEach(b=>b.classList.toggle('current',+b.dataset.bassStep===bass.step));
 if(bassWorld.playhead){bassWorld.playhead.visible=bass.step>=0;if(bass.step>=0)bassWorld.playhead.position.copy(bassWorld.cells[bass.step].mesh.position).add(new THREE.Vector3(0,0,.035));}
 const status=(name,phase)=>name+' · '+(!phase.enabled?'OFF':phase.queued?'NEXT MEASURE':('BEAT '+(Math.floor(phase.step/4)+1)+' · STEP '+(phase.step+1)));
 const drumText=status('DRUMS',drum),bassText=status('BASS',bass);
 if(studio.drumSyncLabel)updateWorldLabel(studio.drumSyncLabel,drumText);if(bassWorld.syncLabel)updateWorldLabel(bassWorld.syncLabel,bassText);
 if($('drum-sync'))$('drum-sync').textContent=drumText;if($('bass-sync'))$('bass-sync').textContent=bassText;playUI?.refresh();refreshMIDI();
 if($('drum-play'))$('drum-play').textContent=drum.queued?'Cancel queued drums':drum.enabled?'Stop drums':'Start drums';
}

function openDrums(){let p=panel('Drum machine');p.innerHTML='<p>Make one measure of drums. It repeats four times in each recording loop. Start either machine first; the other joins on beat 1 of the next measure, automatically in sync.</p><div class="row"><button id="drum-play" class="primary">Start drums</button><label>Tempo <input id="bpm" type="number" min="40" max="200" value="'+bpm+'" style="width:70px"> BPM</label><button id="clear-drums" class="secondary">Clear</button></div><div id="drum-presets" class="row"></div><p id="drum-preset-name"></p><div id="drum-harmony"></div><p id="drum-sync" role="status"></p><div class="sequencer" id="sequencer"></div>';
addPresetSelect('drum-presets','drums');addHarmonySelect('drum-harmony','drum');refreshPresetLabels();drums.forEach((d,r)=>{let row=document.createElement('div');row.className='seq-row';let title=document.createElement('span');title.textContent=d.toUpperCase();row.append(title);for(let i=0;i<16;i++){let b=document.createElement('button');b.dataset.seq=r+','+i;b.className=i%4===0?'beat':'';b.setAttribute('aria-label',d+', step '+(i+1));b.onclick=()=>toggleStep(r,i);row.append(b);}$('sequencer').append(row);});$('drum-play').onclick=toggleDrums;$('clear-drums').onclick=clearPattern;$('bpm').onchange=e=>setBpm(Number(e.target.value)||100);const edit=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Edit rhythm & settings';edit.append(summary,$('sequencer'),$('drum-harmony'),$('bpm').parentElement,$('clear-drums'));p.append(edit);updateSequence();}
function parseSource(raw){let u;try{u=new URL(raw.trim());}catch{throw Error('Enter a complete https:// link.');}if(u.protocol!=='https:')throw Error('Use an HTTPS link so it can play in the headset.');let host=u.hostname.toLowerCase().replace(/^www\./,'');if(['youtube.com','m.youtube.com','youtu.be','youtube-nocookie.com'].includes(host)){let id=host==='youtu.be'?u.pathname.split('/')[1]:u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]+)/)?.[1];if(!id||! /^[\w-]{11}$/.test(id))throw Error('Use a link to one YouTube video.');return {kind:'youtube',url:'https://www.youtube.com/watch?v='+id,videoId:id};}return{kind:'direct',url:u.href};}
function safeMedia(items){if(!Array.isArray(items)||items.length>100)throw Error('The setup must contain up to 100 media entries.');return items.map(m=>{if(!m||typeof m.title!=='string'||!['screen','listen'].includes(m.area)||typeof m.url!=='string')throw Error('This setup has an invalid media entry.');return{title:m.title.slice(0,100),area:m.area,...parseSource(m.url)};});}
function saveMedia(){try{localStorage.setItem('drews-vr-media-v1',JSON.stringify(media.filter(m=>!m.local)));}catch{toast('This browser could not save setup. Use Export to keep your links.');}refreshMedia();}
try{media=safeMedia(JSON.parse(localStorage.getItem('drews-vr-media-v1')||'[]'));}catch{media=[];}
function listMedia(area){return media.filter(m=>m.area===area||(area==='listen'&&m.area==='screen'));}
function disposeLabel(m){m.geometry.dispose();m.material.map?.dispose();m.material.dispose();}
