function openTeacher(){let p=panel('Teacher setup');p.innerHTML='<p class="panel-note">Add optional media links or files, then open Teacher media from Settings to play them. Your recordings are in My Songs at the front Song Station. Nothing is loaded by default. Links are saved on this device. Export your setup to bring the same list to another device.</p><form id="media-form"><label class="field">Title<input id="media-title" required maxlength="100" placeholder="e.g. Our spring concert"></label><div class="row"><label class="field">Destination<select id="media-area"><option value="listen">Teacher media</option></select></label><label class="field">Source<select id="media-source"><option value="link">YouTube or direct media link</option><option value="file">File from this device</option></select></label></div><label class="field" id="link-field">Link<input id="media-link" type="url" placeholder="https://…"></label><label class="field" id="file-field" hidden>Media file<input id="media-file" type="file" accept="video/mp4,video/webm,audio/mpeg,audio/wav,audio/ogg,audio/mp4"></label><p id="media-error" class="error" role="alert"></p><button class="primary" type="submit">Add to room</button></form><p style="font-size:12px;color:#667d6b">YouTube cannot appear on the VR television or play as hidden background audio. Use Browser View to watch outside immersive VR. Choose audio files for listening in VR. Local files last for this session and are not included in exported setups.</p><div class="section-title">YOUR MEDIA</div><div id="media-list"></div><div class="section-title">MOVE YOUR SETUP</div><div class="row"><button id="export-setup" class="secondary">Export link list</button><button id="import-setup" class="secondary">Import link list</button></div><input id="import-file" type="file" accept="application/json,.json" hidden><p style="font-size:12px;color:#72816a">These are setup controls, not a teacher login. Other users of this device can edit them.</p>';
$('file-field').style.display='none';$('media-source').onchange=e=>{let local=e.target.value==='file';$('link-field').style.display=local?'none':'flex';$('file-field').style.display=local?'flex':'none';};$('media-form').onsubmit=e=>{e.preventDefault();try{let title=$('media-title').value.trim();if(!title)throw Error('Give this media a title.');let area=$('media-area').value,item;if($('media-source').value==='file'){let f=$('media-file').files[0];if(!f)throw Error('Choose a media file.');if(area==='screen'&&!f.type.startsWith('video/'))throw Error('Choose a video file for the smartboard.');item={title,area,kind:'direct',url:URL.createObjectURL(f),local:true};}else item={title,area,...parseSource($('media-link').value)};if(media.length>=100)throw Error('The room can hold up to 100 media entries.');media.push(item);saveMedia();openTeacher();toast('Added '+title+' to the room.');}catch(err){$('media-error').textContent=err.message;}};
renderMediaList(true);$('export-setup').onclick=()=>{let blob=new Blob([JSON.stringify({format:'drews-music-vr',version:1,media:media.filter(m=>!m.local)},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Mr_Drews_VR_Media_Setup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import-setup').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>500000)throw Error('This setup is too large.');let data=JSON.parse(await file.text());if(data.format!=='drews-music-vr')throw Error('Choose an exported Music Lab setup.');const validated=safeMedia(data.media);if(media.length+validated.length>100)throw Error('Import would exceed the 100-entry limit.');for(const m of validated)if(!media.some(x=>x.url===m.url&&x.area===m.area))media.push(m);saveMedia();openTeacher();toast('Media links imported.');}catch(err){$('media-error').textContent=err.message;}};}
function renderMediaList(edit=false,area){let dest=$('media-list');dest.replaceChildren();let list=area?listMedia(area):media;if(!list.length){let e=document.createElement('div');e.className='empty';e.innerHTML='<b>The shelf is yours to fill.</b>No '+(area==='screen'?'movies':area==='listen'?'songs':'media')+' loaded.';dest.append(e);return;}list.forEach((m,i)=>{let row=document.createElement('div');row.className='media-item';let txt=document.createElement('span');txt.textContent=m.title;let small=document.createElement('small');small.textContent='Teacher media'+' · '+(m.local?'Local file · this session':m.kind==='youtube'?'YouTube · browser player':'Direct media');txt.append(small);let b=document.createElement('button');b.className='secondary';b.textContent=edit?'Remove':m.kind==='youtube'?'Browser view':'Play';b.onclick=()=>{if(edit){if(activeMedia===m)stopMedia();media.splice(media.indexOf(m),1);if(m.local)URL.revokeObjectURL(m.url);saveMedia();renderMediaList(true);}else{selectedMedia[area]=i;refreshMedia();playMedia(area);}};row.append(txt,b);dest.append(row);});}
