function synthVisualHeld(visual){return [...synthHolds.values()].some(h=>h.visual===visual);}
function updateSynthHoldVisual(visual){if(!visual)return;const held=synthVisualHeld(visual);visual.classList?.toggle('playing',held);if(visual.material?.emissive){visual.material.emissive.setHex(held?0x42c6ca:0);visual.material.emissiveIntensity=held?.65:0;}}
function holdSynth(token,midi,visual,velocity=.75){if(!soundOn||!audio.soundfont)return false;if(!isAllowed(midi))return false;if(current.type!=='synth')selectStation('synth',false);releaseSynth(token);const release=synth.noteOn(midi,velocity);synthHolds.set(token,{release,visual,midi});updateSynthHoldVisual(visual);$('note-readout').textContent=noteName(midi)+' · SYNTH · HOLD';return true;}
function releaseSynth(token){const h=synthHolds.get(token);if(!h)return;h.release();synthHolds.delete(token);updateSynthHoldVisual(h.visual);}
function releaseSynthHolds(){midiInput?.releaseAll();for(const token of [...synthHolds.keys()])releaseSynth(token);synth.allOff();}
function updateSynthMallet(con,strike,tip,speed){
  const token=con.userData.malletToken,held=synthHolds.get(token)?.visual;
  if(held&&strike.contacts.has(held))return false;
  // A held key gets first priority; a new neighboring contact requires entry.
  const fresh=[...strike.contacts].filter(m=>m.userData.spec.type==='synth'&&!con.userData.contacts.has(m)&&isAllowed(m.userData.midi));
  let next=fresh.includes(strike.hit)?strike.hit:fresh.sort((a,b)=>b.position.y-a.position.y)[0];
  if(held&&!next&&malletStillTouches(held,tip))return false;
  releaseSynth(token);
  // Even a very light touch opens the gate. Swept-only hits last one frame,
  // rather than imposing the old 480 ms tap length on every synth note.
  if(!next&&speed>.12&&strike.hit?.userData.spec.type==='synth')next=strike.hit;
  if(!next)return false;
  return holdSynth(token,next.userData.midi,next,malletVelocity(speed));
}
function updateWorldLabel(mesh,text,color=mesh.userData.textColor||'#e3f6ff'){if(mesh.userData.lastText===text&&mesh.userData.lastColor===color)return;mesh.userData.lastText=text;mesh.userData.lastColor=color;const canvas=mesh.userData.canvas,ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`500 ${Math.min(canvas.height*.58,canvas.width/Math.max(1,text.length*.63))}px sans-serif`;ctx.fillText(text,canvas.width/2,canvas.height/2,canvas.width*.94);const atlas=mesh.userData.atlas;if(atlas){const ac=atlas.canvas.getContext('2d');ac.clearRect(atlas.x,atlas.y,atlas.w,atlas.h);ac.drawImage(canvas,atlas.x,atlas.y);atlas.texture.needsUpdate=true;}else mesh.material.map.needsUpdate=true;}
function setSynth(key,value){if(synth.patch[key]===value)return;const p=SYNTH_PARAMS.find(p=>p.key===key);if(p&&Math.abs(synth.patch[key]-value)<(p.max-p.min)*.0003)return;synth.set(key,value);synthPreset='Custom';refreshSynth();}
function useSynthPreset(name){releaseSynthHolds();synth.preset(name);synthPreset=name;refreshSynth();}
function refreshSynth(){refreshEasySynth();refreshSoundExplorer();for(const c of synthWorld.sliders){const value=synth.patch[c.p.key];c.knob.position.x=c.left+c.width*normalized(c.p,value);updateWorldLabel(c.value,formatParam(c.p,value));}for(const c of synthWorld.choices)c.mesh.material.color.setHex(synth.patch[c.key]===c.value?0xe4a936:0x294471);if(synthWorld.preset)updateWorldLabel(synthWorld.preset,synthPreset);for(const p of SYNTH_PARAMS){const input=$('synth-'+p.key);if(input){input.value=normalized(p,synth.patch[p.key]);$('value-'+p.key).textContent=formatParam(p,synth.patch[p.key]);}}for(const key of ['wave','filter','mod']){const input=$('synth-'+key);if(input)input.value=synth.patch[key];}if($('synth-preset'))$('synth-preset').value=synthPreset in SYNTH_PRESETS?synthPreset:'';drawSynthGraphs();}
