function isInteractionVisible(object){for(let p=object;p;p=p.parent)if(!p.visible)return false;return true;}
function saveComfort(){try{localStorage.setItem('drews-vr-comfort-v1',JSON.stringify({seated:comfort.seated,target:comfort.target}));}catch{toast('Height settings apply now but could not be saved on this device.');}}
function resetControllerMotion(){for(const con of controllers){con.userData.hasPrev=false;con.userData.contacts.clear();con.userData.dragSlider=null;}releaseSynthHolds();}
function refreshComfort(){const mode=comfort.seated?'Seated':'Standing';$('comfort').textContent=comfort.seated?'Seated · height':'Seated / height';if($('seated-toggle'))$('seated-toggle').checked=comfort.seated;if($('seated-height')){$('seated-height').value=Math.round(comfort.target*100);$('seated-height').disabled=!comfort.seated;}if($('seated-height-value'))$('seated-height-value').textContent=Math.round(comfort.target*100)+' cm';if($('comfort-calibrate'))$('comfort-calibrate').disabled=!comfort.seated;if($('comfort-message'))$('comfort-message').textContent=comfort.pending?'Waiting for headset tracking…':renderer?.xr.isPresenting?'Sit naturally, look forward, then recalibrate if needed.':'Your sitting position will be calibrated when you enter VR.';if(comfort.status)updateWorldLabel(comfort.status,comfort.pending?'Waiting for tracking…':mode+(comfort.seated?' · eye height '+Math.round(comfort.target*100)+' cm':''));for(const b of comfort.buttons)b.mesh.material.color.setHex(comfort.seated===b.seated?0xe2a83a:0x294d77);}
function setSeated(enabled){comfort.seated=!!enabled;if(!comfort.seated){comfort.pending=false;comfort.offset=0;if(rig)rig.position.y=0;if(camera&&!renderer?.xr.isPresenting)camera.position.y=1.7;resetControllerMotion();}else if(renderer?.xr.isPresenting){comfort.pending=true;}else if(camera)camera.position.y=comfort.target;saveComfort();refreshComfort();positionComfortMenu();}
function adjustSeatedHeight(value){if(!Number.isFinite(value))return;const next=Math.max(1.1,Math.min(2.1,value)),difference=next-comfort.target;comfort.target=next;if(!comfort.seated){setSeated(true);return;}if(renderer?.xr.isPresenting){if(!comfort.pending&&comfort.rawHeight!==null){comfort.offset+=difference;rig.position.y=comfort.offset;rig.updateMatrixWorld(true);resetControllerMotion();}}else if(camera)camera.position.y=next;saveComfort();refreshComfort();positionComfortMenu();}
function recalibrateSeated(){if(!comfort.seated)setSeated(true);comfort.pending=!!renderer?.xr.isPresenting;if(!renderer?.xr.isPresenting)toast('Sit comfortably, then enter VR to calibrate your playing height.');refreshComfort();}
function onComfortReferenceReset(){comfort.rawHeight=null;comfort.pending=comfort.seated;refreshComfort();}
function updateComfortPose(frame){if(!renderer?.xr.isPresenting||!frame)return;const reference=renderer.xr.getReferenceSpace();if(!reference)return;if(reference!==comfort.reference){comfort.reference?.removeEventListener('reset',onComfortReferenceReset);comfort.reference=reference;reference.addEventListener('reset',onComfortReferenceReset);comfort.pending=comfort.seated;}const pose=frame.getViewerPose(reference);if(!pose)return;const height=pose.transform.position.y;if(!Number.isFinite(height))return;comfort.rawHeight=height;if(comfort.seated&&comfort.pending){comfort.offset=comfort.target-height;rig.position.y=comfort.offset;rig.updateMatrixWorld(true);comfort.pending=false;resetControllerMotion();refreshComfort();positionComfortMenu();}}
function openComfort(){const p=panel('Seated play & height');p.innerHTML='<p>Play from a chair at a comfortable instrument height.</p><label class="seated-mode"><input id="seated-toggle" type="checkbox"><span><b>Seated mode</b><small>Raise your view and controller mallets together.</small></span></label><label class="field">Playing eye height <output id="seated-height-value"></output><input id="seated-height" type="range" min="110" max="210" step="5"></label><div class="row"><button class="secondary" id="comfort-calibrate">Recalibrate sitting position</button><button class="secondary" id="comfort-default">Reset to 160 cm</button></div><p id="comfort-message" role="status"></p><p class="panel-note">Sit naturally before entering VR. Use the left thumbstick click, then choose HEIGHT in the recorder, to open these controls in VR. You can adjust height and switch instruments without standing up. Settings are remembered on this device.</p>';$('seated-toggle').onchange=e=>setSeated(e.target.checked);$('seated-height').oninput=e=>adjustSeatedHeight(+e.target.value/100);$('comfort-calibrate').onclick=recalibrateSeated;$('comfort-default').onclick=()=>adjustSeatedHeight(1.6);refreshComfort();}
function makeComfortMenu(){const g=new THREE.Group();scene.add(g);comfort.menu=g;box(1.12,.79,.045,0x132e52,0,0,0,g);label('SEATED PLAY / HEIGHT',0,.30,.035,.94,.075,g,'#c6f5ff');comfort.status=label('',0,.20,.035,.96,.07,g,'#ffce79');for(const [enabled,x,text]of [[true,-.25,'SEATED'],[false,.25,'STANDING']]){const mesh=button3(text,x,.085,.04,.45,.10,()=>setSeated(enabled),g);comfort.buttons.push({mesh,seated:enabled});}button3('LOWER −5 cm',-.25,-.055,.04,.45,.10,()=>adjustSeatedHeight(comfort.target-.05),g);button3('HIGHER +5 cm',.25,-.055,.04,.45,.10,()=>adjustSeatedHeight(comfort.target+.05),g);button3('RECALIBRATE',-.25,-.195,.04,.45,.10,recalibrateSeated,g);button3('CLOSE',.25,-.195,.04,.45,.10,()=>g.visible=false,g);button3('‹ INSTRUMENT',-.25,-.325,.04,.45,.08,()=>stepComfortStation(-1),g);button3('INSTRUMENT ›',.25,-.325,.04,.45,.08,()=>stepComfortStation(1),g);g.visible=false;refreshComfort();}
function positionComfortMenu(){if(!comfort.menu?.visible||!renderer?.xr.isPresenting)return;rig.updateMatrixWorld(true);renderer.xr.updateCamera(camera);const head=renderer.xr.getCamera(camera),position=head.getWorldPosition(new THREE.Vector3()),forward=new THREE.Vector3(0,0,-1).applyQuaternion(head.getWorldQuaternion(new THREE.Quaternion()));forward.y=0;if(forward.lengthSq()<.001)forward.set(-Math.sin(yaw),0,-Math.cos(yaw));forward.normalize();comfort.menu.position.copy(position).addScaledVector(forward,.88);comfort.menu.position.y=position.y-.10;comfort.menu.rotation.set(0,Math.atan2(-forward.x,-forward.z),0);comfort.menu.updateMatrixWorld(true);}
function toggleComfortMenu(){if(!comfort.menu||!renderer?.xr.isPresenting)return;comfort.menu.visible=!comfort.menu.visible;resetControllerMotion();refreshComfort();positionComfortMenu();}
function stepComfortStation(direction){const index=specs.indexOf(current);selectStation(specs[(index+direction+specs.length)%specs.length].id);positionComfortMenu();}

