async function saveCurrentSong(){if(studio.saving)return;if(recorder.taking)stopRecording();if(!activeSongSource().hasContent){studioNotice('Record a little music first.');return;}studio.saving=true;try{const title=studio.title.trim()||'My song '+(studio.shelf.length+1),saved=await songStore.save(activeSongSource().snapshot(title));studio.lastSaved=saved;studio.shelf=[saved,...studio.shelf.filter(s=>s.id!==saved.id)];studio.storageError=null;studio.selected=0;refreshSongShelf();scheduleRecovery();studioNotice('Saved “'+title+'” on this device.');if(studio.menuStatus)updateWorldLabel(studio.menuStatus,'Saved · '+title);if(studio.shelfStatus)updateWorldLabel(studio.shelfStatus,'Saved · '+title);return true;}catch(e){studioNotice(e.message,8);return false;}finally{studio.saving=false;}}
function exportSong(song){try{const data=validateSong(song||recorder.snapshot(studio.title||'My song'));if(!data.events.length&&!data.drumPattern?.some(row=>row.some(Boolean))&&!data.bassPattern?.steps.some(Boolean))throw Error('Record a song first.');if(!song&&recorder.taking)throw Error('Finish this take before exporting.');const blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=data.title.replace(/[^a-z0-9_-]+/gi,'_')+'.musiclab.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}}
