function stopPreview(){if(!studio.startingGallery){gallery.playRequest++;gallery.loadingId=null;}if(galleryPlayer.state!=='stopped'){galleryPlayer.stop(studioNow());silenceRecordedSynths();gallery.message='Stopped';gallery.loadingId=null;refreshGallery();}studio.wallPreview=false;const wasPlaying=songPreview.state==='playing';songPreview.stop(studioNow());studio.previewId=null;if(wasPlaying)silenceRecordedSynths();refreshSongShelf();refreshGallery();}
