function selectBassStep(i){bassWorld.selected=i;if(!bassPattern.steps[i]){delete bassPattern.presetName;bassPattern.steps[i]={midi:degreeNote(0,recorder.harmony),accent:false,slide:false};syncBass();}refreshBass();}
function selectedBassNote(){delete bassPattern.presetName;return bassPattern.steps[bassWorld.selected]||(bassPattern.steps[bassWorld.selected]={midi:degreeNote(0,recorder.harmony),accent:false,slide:false});}
function changeBassPitch(delta){const s=selectedBassNote();s.midi=nextScaleNote(s.midi,delta,recorder.harmony);syncBass();}
function toggleBassRest(){delete bassPattern.presetName;const i=bassWorld.selected;bassPattern.steps[i]=bassPattern.steps[i]?null:{midi:degreeNote(0,recorder.harmony),accent:false,slide:false};syncBass();}
function editBassFlag(key){const s=selectedBassNote();s[key]=!s[key];syncBass();}
function changeBassTone(key,delta){delete bassPattern.presetName;bassPattern[key]=key==='cutoff'?Math.max(100,Math.min(4000,bassPattern[key]*2**delta)):key==='resonance'?Math.max(.5,Math.min(10,bassPattern[key]+delta)):Math.max(.06,Math.min(.6,bassPattern[key]+delta));syncBass();}
function cycleBassWave(){delete bassPattern.presetName;const waves=['sawtooth','square','triangle'];bassPattern.wave=waves[(waves.indexOf(bassPattern.wave)+1)%3];syncBass();}
function nextBassPreset(){const names=Object.keys(BASS_PRESETS);chooseBassPreset(names[(bassWorld.preset+1)%names.length]);}
function clearBass(){bassPattern=emptyBass();syncBass();}
function syncBass(){if(recorder.bassPattern)recorder.bassPattern=bassPattern;recorder.visualRevision++;refreshBass();}
