function refreshSoundExplorer(){for(const c of synthWorld.envelopes||[]){const shape=SIMPLE_ENVELOPES[c.name];c.mesh.material.color.setHex(Object.entries(shape).every(([key,value])=>Math.abs(synth.patch[key]-value)<.0001)?0x94703a:0x285467);}if(synthWorld.envelopeGraph){drawEnvelope(synthWorld.envelopeGraph.canvas,synth.patch);synthWorld.envelopeGraph.texture.needsUpdate=true;}document.querySelectorAll('[data-wave-choice]').forEach(b=>b.classList.toggle('active',b.dataset.waveChoice===synth.patch.wave));document.querySelectorAll('[data-envelope-choice]').forEach(b=>b.classList.toggle('active',Object.entries(SIMPLE_ENVELOPES[b.dataset.envelopeChoice]).every(([key,value])=>Math.abs(synth.patch[key]-value)<.0001)));}
