function openMixer(page=0){const source=activeSongSource(),parts=songParts(source);experience.mixerPage=page;
 if(renderer?.xr.isPresenting){const pages=Math.max(1,Math.ceil(parts.length/3));page=Math.max(0,Math.min(pages-1,page));showSongDialog('Recorded parts · Mixer',parts.length?'Quieter / louder · mute keeps your notes':'Record a part to see it here.',[]);const g=studio.auxPanel;g.userData.mixer=true;const back=g.children[0];back.scale.y=1.85;back.position.y=-.36;parts.slice(page*3,page*3+3).forEach((part,i)=>{const y=-.03-i*.31;label(part.name+' · '+Math.round(part.volume*100)+'%'+(part.muted?' · MUTED':''),0,y,.065,1.73,.09,g,part.color);button3('QUIETER',-.59,y-.13,.065,.53,.12,()=>{setPartVolume(part.id,part.volume-.1);openMixer(page);},g);button3('LOUDER',0,y-.13,.065,.53,.12,()=>{setPartVolume(part.id,part.volume+.1);openMixer(page);},g);button3(part.muted?'UNMUTE':'MUTE',.59,y-.13,.065,.53,.12,()=>{togglePartMute(part.id);openMixer(page);},g);});button3('BACK',-.62,-1.05,.065,.52,.13,()=>page>0?openMixer(page-1):openCreativeHub(),g);button3('DONE',0,-1.05,.065,.52,.13,closeCreativePanel,g);if(page+1<pages)button3('MORE',.62,-1.05,.065,.52,.13,()=>openMixer(page+1),g);return;}
 const p=panel('Recorded parts · Mixer'),intro=document.createElement('p');intro.textContent='Balance the instruments in your recording. Levels and mutes are saved with the song. Live practice uses your normal playing strength.';p.append(intro);const grid=document.createElement('div');grid.id='song-mixer';grid.className='mixer-grid';if(!parts.length){const empty=document.createElement('p');empty.textContent='Record your first part, then return here to balance it.';grid.append(empty);}for(const part of parts){const card=document.createElement('article');card.className='mixer-card';card.style.setProperty('--part-color',part.color);card.dataset.part=part.id;const icon=document.createElement('canvas');icon.className='mixer-icon';icon.setAttribute('aria-hidden','true');drawInstrumentIcon(icon,part.id);const name=document.createElement('h3');name.textContent=part.name;const field=document.createElement('label');field.textContent='Volume ';const out=document.createElement('output');out.textContent=Math.round(part.volume*100)+'%';const input=document.createElement('input');input.type='range';input.min=0;input.max=100;input.step=1;input.value=Math.round(part.volume*100);input.setAttribute('aria-label',part.name+' volume');input.oninput=()=>setPartVolume(part.id,+input.value/100);field.append(out,input);const mute=creativeButton(part.muted?'Unmute':'Mute',()=>togglePartMute(part.id));mute.setAttribute('aria-pressed',String(part.muted));card.append(icon,name,field,mute);grid.append(card);}p.append(grid);const row=document.createElement('div');row.className='row';row.append(creativeButton('Play',playLoop,true),creativeButton('Stop',stopRecording),creativeButton('All parts on',()=>togglePartMute('__all__')),creativeButton('Done',closeCreativePanel));p.append(row);refreshMixer();
}
function refreshMixer(){const grid=$('song-mixer');if(!grid)return;const source=activeSongSource();for(const card of grid.querySelectorAll('[data-part]')){const p=source.mix[card.dataset.part]||{volume:1,muted:false};card.classList.toggle('is-muted',p.muted);const input=card.querySelector('input');if(document.activeElement!==input)input.value=Math.round(p.volume*100);card.querySelector('output').textContent=Math.round(p.volume*100)+'%';const b=card.querySelector('button');b.textContent=p.muted?'Unmute':'Mute';b.setAttribute('aria-pressed',String(p.muted));}}
function setScreenStyle(style){experience.screen=style==='stars'?'stars':'notes';if(noteWall.mesh){noteWall.mesh.material.map=experience.screen==='stars'?noteWall.starTexture:noteWall.texture;noteWall.mesh.material.needsUpdate=true;noteWall.view.key=null;updateNoteWall(studioNow(),performance.now(),true);}if($('performance-screen'))$('performance-screen').value=experience.screen;}
